

import { useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';

export default function AdminLogin() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const urlReason = searchParams.get('reason');

  const formatReason = (reason: string | null) => {
    if (!reason) return null;
    const lower = reason.toLowerCase();
    if (lower.includes('expired')) {
      return 'Token verification failed: token expired, please sign-in again.';
    }
    if (reason.includes('eyJ') || lower.includes('token (')) {
      return 'Token verification failed: session invalid, please sign-in again.';
    }
    return reason;
  };

  const displayReason = formatReason(urlReason);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    try {
      const res = await fetch('/api/admin/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password })
      });
      const data = await res.json();
      if (data.success) {
        navigate('/admin');
      } else {
        setError(data.error || 'Login failed');
      }
    } catch (err) {
      setError('Network error');
    }
  };

  return (
    <>
      <style>
        {`
          @keyframes rainbowCycle {
            0% { filter: hue-rotate(0deg); }
            100% { filter: hue-rotate(360deg); }
          }
          .rainbow-logo {
            animation: rainbowCycle 5s linear infinite;
          }
        `}
      </style>

    {/*  Content  */}

    <div className="authentication-wrapper authentication-cover">
      {/*  Logo  */}
      <a href="index.html" className="auth-cover-brand d-flex align-items-center gap-2">
        <span className="app-brand-logo demo">
          <span className="text-primary rainbow-logo" style={{"display":"inline-block","width":"32px","height":"32px","backgroundColor":"currentColor","maskImage":"url('data:image/png;base64,')","maskSize":"contain","maskRepeat":"no-repeat","maskPosition":"center","WebkitMaskImage":"url('data:image/png;base64,')","WebkitMaskSize":"contain","WebkitMaskRepeat":"no-repeat","WebkitMaskPosition":"center"}}></span>
        </span>
        <span className="app-brand-text demo text-primary rainbow-logo fw-semibold" style={{"fontSize":"2rem"}}>Stamford</span>
      </a>
      {/*  /Logo  */}
      <div className="authentication-inner row m-0">
        {/*  /Left Section  */}
        <div className="d-none d-lg-flex col-lg-7 col-xl-8 align-items-center justify-content-center p-12 pb-2">
          <img
            src="../../assets/img/illustrations/auth-login-illustration-light.png"
            className="auth-cover-illustration w-100"
            alt="auth-illustration"
            data-app-light-img="illustrations/auth-login-illustration-light.png"
            data-app-dark-img="illustrations/auth-login-illustration-dark.png" />
          <img
            alt="mask"
            src="../../assets/img/illustrations/auth-basic-login-mask-light.png"
            className="authentication-image d-none d-lg-block"
            data-app-light-img="illustrations/auth-basic-login-mask-light.png"
            data-app-dark-img="illustrations/auth-basic-login-mask-dark.png" />
        </div>
        {/*  /Left Section  */}

        {/*  Login  */}
        <div
          className="d-flex col-12 col-lg-5 col-xl-4 align-items-center authentication-bg position-relative py-sm-12 px-12 py-6">
          <div className="w-px-400 mx-auto pt-12 pt-lg-0" style={{ maxWidth: '100%' }}>
            <h4 className="mb-1">Welcome to IT Gear</h4>
            <p className="mb-5">Please sign-in to your account and start managing IT equipment.</p>

            <form id="formAuthentication" className="mb-5" onSubmit={handleLogin}>
              {error && (
                <div 
                  className="alert alert-danger" 
                  style={{ wordBreak: 'break-word', overflowWrap: 'anywhere', whiteSpace: 'normal', lineHeight: '1.5' }}
                >
                  {error}
                </div>
              )}
              {displayReason && !error && (
                <div 
                  className="alert alert-warning" 
                  style={{ wordBreak: 'break-word', overflowWrap: 'anywhere', whiteSpace: 'normal', lineHeight: '1.5' }}
                >
                  Redirected: {displayReason}
                </div>
              )}
              <div className="form-floating form-floating-outline mb-5">
                <input
                  type="text"
                  className="form-control"
                  id="username"
                  name="username"
                  placeholder="Enter your username"
                  autoFocus={true}
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  required />
                <label htmlFor="username">Username</label>
              </div>
              <div className="mb-5">
                <div className="form-password-toggle form-control-validation">
                  <div className="input-group input-group-merge">
                    <div className="form-floating form-floating-outline">
                      <input
                        type="password"
                        id="password"
                        className="form-control"
                        name="password"
                        placeholder="&#xb7;&#xb7;&#xb7;&#xb7;&#xb7;&#xb7;&#xb7;&#xb7;&#xb7;&#xb7;&#xb7;&#xb7;"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        required
                        aria-describedby="password" />
                      <label htmlFor="password">Password</label>
                    </div>
                  </div>
                </div>
              </div>
              <button className="btn btn-primary d-grid w-100" type="submit">Sign in</button>
            </form>

            

                      </div>
        </div>
        {/*  /Login  */}
      </div>
    </div>

    {/*  / Content  */}

    
    </>
  );
}
